const upsertGoodsProvider = `-- name: UpsertGoodsProvider :one
INSERT INTO goods_providers (
  slug, enabled, credentials_ciphertext, low_balance_threshold_minor,
  spend_limit_minor, spend_window_seconds
) VALUES (
  $1, $2, $3,
  $4, $5,
  $6
)
ON CONFLICT (slug) DO UPDATE
SET enabled = EXCLUDED.enabled,
    credentials_ciphertext = COALESCE(
      EXCLUDED.credentials_ciphertext, goods_providers.credentials_ciphertext
    ),
    low_balance_threshold_minor = EXCLUDED.low_balance_threshold_minor,
    spend_limit_minor = EXCLUDED.spend_limit_minor,
    spend_window_seconds = EXCLUDED.spend_window_seconds,
    updated_at = now()
RETURNING slug, enabled, credentials_ciphertext, balance_minor, balance_currency, low_balance_threshold_minor, spend_limit_minor, spend_window_seconds, status, last_error_code, last_checked_at, created_at, updated_at
`

type UpsertGoodsProviderParams struct {
	Slug                     string      `json:"slug"`
	Enabled                  bool        `json:"enabled"`
	CredentialsCiphertext    []byte      `json:"credentials_ciphertext"`
	LowBalanceThresholdMinor pgtype.Int8 `json:"low_balance_threshold_minor"`
	SpendLimitMinor          int64       `json:"spend_limit_minor"`
	SpendWindowSeconds       int64       `json:"spend_window_seconds"`
}

// A null ciphertext on update means "leave the stored credential alone", so the
// panel can render and re-save the form without ever echoing a secret back.
func (q *Queries) UpsertGoodsProvider(ctx context.Context, arg UpsertGoodsProviderParams) (GoodsProvider, error) {
	row := q.db.QueryRow(ctx, upsertGoodsProvider,
		arg.Slug,
		arg.Enabled,
		arg.CredentialsCiphertext,
		arg.LowBalanceThresholdMinor,
		arg.SpendLimitMinor,
		arg.SpendWindowSeconds,
	)
	var i GoodsProvider
	err := row.Scan(
		&i.Slug,
		&i.Enabled,
		&i.CredentialsCiphertext,
		&i.BalanceMinor,
		&i.BalanceCurrency,
		&i.LowBalanceThresholdMinor,
		&i.SpendLimitMinor,
		&i.SpendWindowSeconds,
		&i.Status,
		&i.LastErrorCode,
		&i.LastCheckedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
